          <div class="stat-card">
            <div class="stat-label">Processing</div>
            <div class="stat-val">{{ orders.filter(o => o.status.toLowerCase() === 'processing').length }}</div>
          </div>
          <div class="stat-card">
            <div class="stat-label">Completed</div>
            <div class="stat-val">{{ orders.filter(o => o.status.toLowerCase() === 'completed').length }}</div>
          </div>
        </div>

        <div class="orders-table">
          <div class="table-header">
            <div class="col-id">Order #</div>
            <div class="col-customer">Customer</div>
            <div class="col-date">Date</div>
            <div class="col-items">Items</div>
            <div class="col-total">Total</div>
            <div class="col-status">Status</div>
            <div class="col-actions">Actions</div>
