        <!-- Settings sub-tabs -->
        <div class="settings-tabs">
          <button class="stab" :class="{ active: settingsTab === 'activity' }" @click="settingsTab = 'activity'; loadActivityLog()">📜 Activity Log</button>
          <button class="stab" :class="{ active: settingsTab === 'insights' }" @click="settingsTab = 'insights'; loadCustomerInsights()">📊 Customer Insights</button>
        </div>

        <!-- Activity Log -->
        <div v-if="settingsTab === 'activity'" class="settings-panel">
          <div class="activity-filters">
            <select v-model="activityFilters.customerId" @change="loadActivityLog" class="filter-select">
              <option value="">All Customers</option>
              <option v-for="c in customers" :key="c.id" :value="c.id">{{ c.company_name }}</option>
            </select>
            <select v-model="activityFilters.type" @change="loadActivityLog" class="filter-select">
              <option value="all">All Types</option>
              <option value="login">Login</option>
              <option value="order">Order</option>
              <option value="favorite">Favorite</option>
              <option value="toggle">Toggle</option>
            </select>
            <button class="btn-refresh" @click="loadActivityLog">↻ Refresh</button>
          </div>

          <div v-if="activityLoading" class="loading-state">Loading activity…</div>
          <div v-else-if="activities.length === 0" class="empty-state">No activity found.</div>
          <div v-else class="activity-list">
            <div v-for="act in activities" :key="act.id" class="activity-card">
