        <!-- Customer Insights -->
        <div v-if="settingsTab === 'insights'" class="settings-panel">
          <div v-if="insightsLoading" class="loading-state">Loading insights…</div>
          <div v-else-if="!selectedInsightCustomer" class="insights-grid">
            <div v-for="insight in customerInsights" :key="insight.id" class="insight-card" @click="selectedInsightCustomer = insight">
              <div class="insight-avatar">{{ insight.company_name[0].toUpperCase() }}</div>
              <div class="insight-info">
                <h3>{{ insight.company_name }}</h3>
