                  <span v-for="(p, i) in insight.top_products" :key="i" class="top-prod-chip">{{ p.name }}</span>
                </div>
              </div>
            </div>
          </div>

          <!-- Customer detail view -->
          <div v-else class="insight-detail">
            <button class="btn-back" @click="selectedInsightCustomer = null">← Back to Insights</button>
            <div class="insight-detail-card">
              <div class="insight-detail-header">
                <div class="insight-avatar large">{{ selectedInsightCustomer.company_name[0].toUpperCase() }}</div>
                <div>
                  <h2>{{ selectedInsightCustomer.company_name }}</h2>
                  <p>{{ selectedInsightCustomer.contact_name }} · {{ selectedInsightCustomer.email }}</p>
                  <p class="preset-badge">View preset: {{ selectedInsightCustomer.view_preset }}</p>
                </div>
              </div>
              <div class="insight-stats large">
                <div class="istat">
                  <div class="istat-val xl">{{ selectedInsightCustomer.total_orders }}</div>
                  <div class="istat-label">Total Orders</div>
                </div>
                <div class="istat">
                  <div class="istat-val xl">{{ selectedInsightCustomer.total_cases }}</div>
                  <div class="istat-label">Total Cases</div>
                </div>
                <div class="istat">
                  <div class="istat-val xl">{{ selectedInsightCustomer.last_order_date ? formatDate(selectedInsightCustomer.last_order_date) : '—' }}</div>
                  <div class="istat-label">Last Order</div>
                </div>
                <div class="istat">
                  <div class="istat-val xl">{{ selectedInsightCustomer.last_login ? formatDate(selectedInsightCustomer.last_login) : '—' }}</div>
                  <div class="istat-label">Last Login</div>
                </div>
              </div>
              <div v-if="selectedInsightCustomer.top_products.length" class="top-prods-detail">
                <h4>Top Products</h4>
                <div v-for="(p, i) in selectedInsightCustomer.top_products" :key="i" class="top-prod-row">
                  <span class="tp-rank">#{{ i + 1 }}</span>
                  <span class="tp-name">{{ p.name }}</span>
                  <span class="tp-qty">{{ p.qty }} units</span>
