              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- ==================== MODALS ==================== -->

    <!-- Add/Edit Product Modal -->
    <div v-if="showAddProductModal" class="modal-overlay" @click.self="showAddProductModal = false">
      <div class="modal">
        <h2>{{ newProduct.id ? 'Edit Product' : 'Add Product' }}</h2>
        <div class="form">
          <div class="form-group">
            <label>Product Name</label>
            <input v-model="newProduct.name" type="text" />
          </div>
          <div class="form-group">
            <label>SKU</label>
            <input v-model="newProduct.sku" type="text" />
          </div>
          <div class="form-group">
