            <input v-model.number="newProduct.price" type="number" step="0.01" />
          </div>
          <div class="form-group">
            <label>Category</label>
            <input v-model="newProduct.category" type="text" />
          </div>
          <div class="form-group">
            <label>Image URL</label>
            <input v-model="newProduct.image_url" type="text" />
          </div>
          <div class="form-group">
            <label>
              <input v-model="newProduct.visible" type="checkbox" />
              Visible
            </label>
          </div>
        </div>
        <div class="modal-buttons">
          <button class="btn-cancel" @click="showAddProductModal = false">Cancel</button>
          <button class="btn-save" @click="saveProduct">Save</button>
        </div>
      </div>
    </div>

    <!-- Add Customer Modal -->
    <div v-if="showAddCustomerModal" class="modal-overlay" @click.self="showAddCustomerModal = false">
      <div class="modal">
        <h2>Add Customer</h2>
        <div class="form">
          <div class="form-group">
            <label>Company Name</label>
            <input v-model="newCustomer.company_name" type="text" />
          </div>
          <div class="form-group">
            <label>Email</label>
            <input v-model="newCustomer.email" type="email" />
          </div>
          <div class="form-group">
            <label>Password</label>
            <input v-model="newCustomer.password" type="password" />
          </div>
        </div>
        <div class="modal-buttons">
          <button class="btn-cancel" @click="showAddCustomerModal = false">Cancel</button>
          <button class="btn-save" @click="saveCustomer">Save</button>
        </div>
      </div>
    </div>

    <!-- Customer Visibility Modal -->
    <div v-if="showVisibilityModal && visibilityCustomer" class="modal-overlay" @click.self="closeVisibilityModal">
      <div class="modal modal-wide">
        <h2>👁 Visibility — {{ visibilityCustomer.company_name }}</h2>
        <p class="modal-sub">Control which categories and products this customer can see.</p>

        <div v-if="visibilityLoading" class="loading-state" style="padding:20px">Loading…</div>
        <div v-else>
          <!-- Category toggles -->
          <div class="section-label">Category Visibility</div>
          <div class="toggle-grid">
            <div v-for="cat in superCategories" :key="cat.id" class="toggle-row">
              <label class="toggle-label">
                <input
                  type="checkbox"
                  :checked="!visibilityData.catHidden.includes(cat.id)"
                  @change="toggleCatVisibility(cat.id, $event.target.checked)"
                  class="toggle-check"
                />
                <span class="toggle-name">{{ cat.name }}</span>
              </label>
              <span class="toggle-hint" :class="visibilityData.catHidden.includes(cat.id) ? 'hidden-txt' : 'visible-txt'">
                {{ visibilityData.catHidden.includes(cat.id) ? 'Hidden' : 'Visible' }}
              </span>
            </div>
          </div>

          <!-- Product-level overrides -->
          <div class="section-label" style="margin-top:18px">Product-Level Overrides</div>
          <div class="prod-search-bar">
            <input v-model="visibilityProductSearch" type="text" placeholder="Search products…" />
          </div>
          <div class="toggle-grid prod-toggle-grid">
            <div v-for="product in visibilityFilteredProducts" :key="product.id" class="toggle-row">
              <label class="toggle-label">
                <input
                  type="checkbox"
                  :checked="!visibilityData.hiddenProducts.includes(product.id)"
                  @change="toggleProductHidden(product.id, $event.target.checked)"
                  class="toggle-check"
                />
                <span class="toggle-name">{{ product.name }}</span>
                <span class="sku-small">{{ product.sku }}</span>
              </label>
              <span class="toggle-hint" :class="visibilityData.hiddenProducts.includes(product.id) ? 'hidden-txt' : 'visible-txt'">
                {{ visibilityData.hiddenProducts.includes(product.id) ? 'Hidden' : 'Visible' }}
              </span>
            </div>
          </div>
        </div>

        <div class="modal-buttons" style="margin-top:20px">
          <button class="btn-cancel" @click="closeVisibilityModal">Cancel</button>
          <button class="btn-save" @click="saveVisibilityOverrides">Save Changes</button>
        </div>
      </div>
    </div>

    <!-- Toast -->
    <div v-if="toast.show" class="toast" :class="toast.type">
      {{ toast.message }}
    </div>
  </div>
</template>

<script setup>
import { ref, computed, onMounted } from 'vue'
import axios from 'axios'
import draggable from 'vuedraggable'

const props = defineProps({
  user: { type: Object, required: true }
})
const emit = defineEmits(['logout'])

// ─── State ───────────────────────────────────────────────
const products = ref([])
const orders = ref([])
const customers = ref([])
const superCategories = ref([])

// UI State
const currentTab = ref('catalog')
const sidebarOpen = ref(false)
const catalogSearch = ref('')
const orderFilter = ref('all')
const toast = ref({ show: false, message: '', type: 'info' })

// Catalog - Reorder
const reorderMode = ref(false)

// Settings sub-tabs
const settingsTab = ref('activity')

// Activity log
const activities = ref([])
const activityLoading = ref(false)
const activityFilters = ref({ customerId: '', type: 'all' })

// Customer insights
const customerInsights = ref([])
const insightsLoading = ref(false)
const selectedInsightCustomer = ref(null)

// Customer visibility modal
const showVisibilityModal = ref(false)
const visibilityCustomer = ref(null)
const visibilityData = ref({ catHidden: [], hiddenProducts: [] })
const visibilityLoading = ref(false)
const visibilityProductSearch = ref('')

// Modals
const showAddProductModal = ref(false)
const showAddCustomerModal = ref(false)

const newProduct = ref({ name: '', sku: '', price: 0, category: '', image_url: '', visible: true })
const newCustomer = ref({ company_name: '', email: '', password: '' })

// ─── Auth Header ─────────────────────────────────────────
const authHeader = () => {
  const token = localStorage.getItem('authToken')
  return token ? { Authorization: `Bearer ${token}` } : {}
}

// ─── Computed ────────────────────────────────────────────
const filteredProducts = computed(() => {
  if (!catalogSearch.value) return products.value
  const q = catalogSearch.value.toLowerCase()
  return products.value.filter(p =>
    p.name.toLowerCase().includes(q) || p.sku.toLowerCase().includes(q)
  )
})

const filteredOrders = computed(() => {
  if (orderFilter.value === 'all') return orders.value
  return orders.value.filter(o => o.status.toLowerCase() === orderFilter.value)
})

const visibilityFilteredProducts = computed(() => {
  if (!visibilityProductSearch.value) return products.value
  const q = visibilityProductSearch.value.toLowerCase()
  return products.value.filter(p =>
    p.name.toLowerCase().includes(q) || p.sku.toLowerCase().includes(q)
  )
})

// ─── Fetch Methods ───────────────────────────────────────
const fetchProducts = async () => {
  try {
    const response = await axios.get(`${import.meta.env.VITE_API_URL}/api/products`, { headers: authHeader() })
    // Map API field names to component field names
    const data = response.data.products || response.data
    products.value = data.map(p => ({
      ...p,
      visible: !p.is_hidden,      // Invert: is_hidden → visible
      in_stock: !p.is_oos,        // Invert: is_oos → in_stock
      price: p.price || 0         // Ensure price exists
    }))
  } catch (err) {
    showToast('Failed to load products', 'error')
  }
}

const fetchOrders = async () => {
  try {
    const response = await axios.get(`${import.meta.env.VITE_API_URL}/api/orders`, { headers: authHeader() })
    orders.value = response.data.orders || response.data
  } catch (err) {
    showToast('Failed to load orders', 'error')
  }
}

const fetchCustomers = async () => {
  try {
    const response = await axios.get(`${import.meta.env.VITE_API_URL}/api/admin/customers`, { headers: authHeader() })
    customers.value = response.data.customers || response.data
  } catch (err) {
    showToast('Failed to load customers', 'error')
  }
}

const fetchSuperCategories = async () => {
  try {
    const response = await axios.get(`${import.meta.env.VITE_API_URL}/api/admin/categories`, { headers: authHeader() })
    superCategories.value = response.data.categories || []
  } catch (err) {
    console.warn('Could not load categories', err)
  }
}

// ─── Activity Log ─────────────────────────────────────────
const loadActivityLog = async () => {
  activityLoading.value = true
  try {
    const params = { limit: 100 }
    if (activityFilters.value.customerId) params.customer_id = activityFilters.value.customerId
    if (activityFilters.value.type && activityFilters.value.type !== 'all') params.type = activityFilters.value.type
    const response = await axios.get(`${import.meta.env.VITE_API_URL}/api/admin/activity-log`, {
      headers: authHeader(),
      params
    })
    activities.value = response.data.activities || []
  } catch (err) {
    showToast('Failed to load activity log', 'error')
  } finally {
    activityLoading.value = false
  }
}

const activityIcon = (type) => {
  const icons = { login: '🔑', order: '📦', favorite: '❤️', toggle: '🔀' }
  return icons[type] || '📋'
}

// ─── Customer Insights ────────────────────────────────────
const loadCustomerInsights = async () => {
  insightsLoading.value = true
  try {
    const response = await axios.get(`${import.meta.env.VITE_API_URL}/api/admin/customer-insights`, { headers: authHeader() })
    customerInsights.value = response.data.insights || []
  } catch (err) {
    showToast('Failed to load customer insights', 'error')
  } finally {
    insightsLoading.value = false
  }
}

// ─── Drag-drop Reorder ───────────────────────────────────
const toggleReorderMode = async () => {
  if (reorderMode.value) {
    // Save current order
    await saveProductOrder()
    reorderMode.value = false
  } else {
    reorderMode.value = true
  }
}

const exitReorderMode = () => {
  reorderMode.value = false
}

const onReorderEnd = async () => {
  // Auto-save on each drop
  await saveProductOrder()
}

const saveProductOrder = async () => {
  try {
    const productIds = products.value.map(p => p.id)
    await axios.post(`${import.meta.env.VITE_API_URL}/api/admin/reorder-products`, { productIds }, { headers: authHeader() })
    showToast('Order saved', 'success')
  } catch (err) {
    showToast('Failed to save order', 'error')
  }
}

// ─── Customer Visibility ──────────────────────────────────
const openVisibilityModal = async (customer) => {
  visibilityCustomer.value = customer
  visibilityData.value = { catHidden: [], hiddenProducts: [] }
  visibilityProductSearch.value = ''
  showVisibilityModal.value = true
  visibilityLoading.value = true

  try {
    const response = await axios.get(
      `${import.meta.env.VITE_API_URL}/api/admin/customer-overrides/${customer.id}`,
      { headers: authHeader() }
    )
    visibilityData.value = {
      catHidden: response.data.catHidden || [],
      hiddenProducts: response.data.hiddenProducts || []
    }
  } catch (err) {
    showToast('Failed to load visibility settings', 'error')
  } finally {
    visibilityLoading.value = false
  }
}

const closeVisibilityModal = () => {
  showVisibilityModal.value = false
  visibilityCustomer.value = null
}

const toggleCatVisibility = (catId, isVisible) => {
  if (isVisible) {
    visibilityData.value.catHidden = visibilityData.value.catHidden.filter(id => id !== catId)
  } else {
    if (!visibilityData.value.catHidden.includes(catId)) {
      visibilityData.value.catHidden.push(catId)
    }
  }
}

const toggleProductHidden = (productId, isVisible) => {
  if (isVisible) {
    visibilityData.value.hiddenProducts = visibilityData.value.hiddenProducts.filter(id => id !== productId)
  } else {
    if (!visibilityData.value.hiddenProducts.includes(productId)) {
      visibilityData.value.hiddenProducts.push(productId)
    }
  }
}

const saveVisibilityOverrides = async () => {
  try {
    await axios.post(`${import.meta.env.VITE_API_URL}/api/admin/customer-overrides`, {
      customerId: visibilityCustomer.value.id,
      catHidden: visibilityData.value.catHidden,
      hiddenProducts: visibilityData.value.hiddenProducts
    }, { headers: authHeader() })
    showToast('Visibility saved', 'success')
    closeVisibilityModal()
  } catch (err) {
    showToast('Failed to save visibility', 'error')
  }
}

// ─── Product CRUD ─────────────────────────────────────────
const saveProduct = async () => {
  try {
    if (newProduct.value.id) {
      await axios.put(`${import.meta.env.VITE_API_URL}/api/products/${newProduct.value.id}`, newProduct.value, { headers: authHeader() })
    } else {
      await axios.post(`${import.meta.env.VITE_API_URL}/api/products`, newProduct.value, { headers: authHeader() })
    }
    showAddProductModal.value = false
    newProduct.value = { name: '', sku: '', price: 0, category: '', image_url: '', visible: true }
    showToast('Product saved', 'success')
    await fetchProducts()
  } catch (err) {
    showToast('Failed to save product', 'error')
  }
}

const editProduct = (product) => {
  newProduct.value = { ...product }
  showAddProductModal.value = true
}

const deleteProduct = async (id) => {
  if (!confirm('Delete this product?')) return
  try {
    await axios.delete(`${import.meta.env.VITE_API_URL}/api/products/${id}`, { headers: authHeader() })
    showToast('Product deleted', 'success')
    await fetchProducts()
  } catch (err) {
    showToast('Failed to delete product', 'error')
  }
}

const toggleProductVisibility = async (id) => {
  const product = products.value.find(p => p.id === id)
  if (product) {
    try {
      // API expects is_hidden (inverted), so send the opposite of current visible state
      await axios.patch(`${import.meta.env.VITE_API_URL}/api/products/${id}`, { is_hidden: product.visible }, { headers: authHeader() })
      product.visible = !product.visible
      showToast('Product updated', 'success')
    } catch (err) {
      showToast('Failed to update product', 'error')
    }
  }
}

const openAddProductModal = () => {
  newProduct.value = { name: '', sku: '', price: 0, category: '', image_url: '', visible: true }
  showAddProductModal.value = true
}

// ─── Customer CRUD ────────────────────────────────────────
const saveCustomer = async () => {
  try {
    await axios.post(`${import.meta.env.VITE_API_URL}/api/admin/customers`, newCustomer.value, { headers: authHeader() })
    showAddCustomerModal.value = false
    newCustomer.value = { company_name: '', email: '', password: '' }
    showToast('Customer added', 'success')
    await fetchCustomers()
  } catch (err) {
    showToast('Failed to add customer', 'error')
  }
}

const editCustomer = (customer) => {
  // Future: open edit modal
}

const deleteCustomer = async (id) => {
  if (!confirm('Delete this customer?')) return
  try {
    await axios.delete(`${import.meta.env.VITE_API_URL}/api/admin/customers/${id}`, { headers: authHeader() })
    showToast('Customer deleted', 'success')
    await fetchCustomers()
  } catch (err) {
    showToast('Failed to delete customer', 'error')
  }
}

const customerOrders = (customerId) => {
  return orders.value.filter(o => o.customer_id === customerId)
}

const openAddCustomerModal = () => {
  newCustomer.value = { company_name: '', email: '', password: '' }
  showAddCustomerModal.value = true
}

// ─── Orders ───────────────────────────────────────────────
const updateOrderStatus = async (orderId, status) => {
  try {
    await axios.put(`${import.meta.env.VITE_API_URL}/api/orders/${orderId}/status`, { status }, { headers: authHeader() })
    const order = orders.value.find(o => o.id === orderId)
    if (order) order.status = status
    showToast('Order updated', 'success')
  } catch (err) {
    showToast('Failed to update order', 'error')
  }
}

const viewOrder = (order) => {
  alert(JSON.stringify(order, null, 2))
}

// ─── Utilities ────────────────────────────────────────────
const toggleSidebar = () => { sidebarOpen.value = !sidebarOpen.value }
const handleLogout = () => { emit('logout') }

const showToast = (message, type = 'info') => {
  toast.value = { show: true, message, type }
  setTimeout(() => { toast.value.show = false }, 3000)
}

const formatDate = (date) => new Date(date).toLocaleDateString()
const formatDateTime = (date) => {
  const d = new Date(date)
  return d.toLocaleDateString() + ' ' + d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
}

// ─── Lifecycle ────────────────────────────────────────────
onMounted(() => {
  fetchProducts()
  fetchOrders()
  fetchCustomers()
  fetchSuperCategories()
})
</script>

